from dataclasses import dataclass
from typing import Iterable

@dataclass(frozen=True)
class Event:
    name: str
    start: int
    end: int

def reserve_slots(events: Iterable[Event], limit: int) -> list[Event]:
    """Return non-overlapping events, preferring earlier finishes."""
    if limit < 0:
        raise ValueError("limit must be non-negative")
    ordered = sorted(events, key=lambda event: (event.end, event.start, event.name))
    chosen: list[Event] = []
    last_end: int | None = None
    for event in ordered:
        if event.start > event.end:
            raise ValueError(f"invalid interval: {event.name}")
        # Touching intervals can share a boundary, so only a real overlap is rejected.
        if last_end is not None and event.start < last_end:
            continue
        chosen.append(event)
        last_end = event.end
        if len(chosen) == limit:
            break
    return chosen

items = [Event("setup", 0, 2), Event("call", 2, 5), Event("blocked", 1, 4)]
assert [item.name for item in reserve_slots(items, 3)] == ["setup", "call"]
assert reserve_slots([], 2) == []
try:
    reserve_slots([Event("bad", 4, 3)], 1)
except ValueError:
    pass
else:
    raise AssertionError("an inverted interval must fail")

type Entry = { key: string; value: number };

export function summarize(entries: readonly Entry[]): Map<string, number> {
  const totals = new Map<string, number>();

  for (const entry of entries) {
    if (!Number.isFinite(entry.value)) {
      throw new TypeError(`non-finite value for ${entry.key}`);
    }
    totals.set(entry.key, (totals.get(entry.key) ?? 0) + entry.value);
  }

  return totals;
}

export function toQuery(params: Readonly<Record<string, string | number | null>>): string {
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    // Null means the caller intentionally omitted this optional field.
    if (value !== null) query.set(key, String(value));
  }
  return query.toString();
}

const result = summarize([
  { key: "apples", value: 2 },
  { key: "oranges", value: 3.5 },
  { key: "apples", value: 1 },
]);
if (result.get("apples") !== 3 || result.get("oranges") !== 3.5) {
  throw new Error("summary did not preserve totals");
}
if (toQuery({ page: 2, filter: null }) !== "page=2") {
  throw new Error("query omitted an explicit null field incorrectly");
}

export function sortedEntries(totals: ReadonlyMap<string, number>): Entry[] {
  // Sorting a fresh array keeps the caller's map and its insertion order intact.
  return [...totals.entries()]
    .map(([key, value]) => ({ key, value }))
    .sort((left, right) => left.key.localeCompare(right.key));
}

const ordered = sortedEntries(result);
if (ordered.map((entry) => entry.key).join(",") !== "apples,oranges") {
  throw new Error("entries were not sorted by key");
}
